240	// Find the number of splits that maximizes the occupancy. For example, if we have
241	// batch * n_heads = 48 and we have 108 SMs, having 2 splits (efficiency = 0.89) is
242	// better than having 3 splits (efficiency = 0.67). However, we also don't want too many
243	// splits as that would incur more HBM reads/writes.
244	// So we find the best efficiency, then find the smallest number of splits that gets 85%
245	// of the best efficiency.
246	inline int num_splits_heuristic(int batch_nheads_mblocks, int num_SMs, int num_n_blocks, int max_splits) {
247	    // If we have enough to almost fill the SMs, then just use 1 split
248	    if (batch_nheads_mblocks >= 0.8f * num_SMs) { return 1; }
249	    max_splits = std::min({max_splits, num_SMs, num_n_blocks});
250	    float max_efficiency = 0.f;
251	    std::vector<float> efficiency;
252	    efficiency.reserve(max_splits);
253	    auto ceildiv = [](int a, int b) { return (a + b - 1) / b; };
254	    // Some splits are not eligible. For example, if we have 64 blocks and choose 11 splits,
255	    // we'll have 6 * 10 + 4 blocks. If we choose 12 splits, we'll have 6 * 11 + (-2) blocks
256	    // (i.e. it's 11 splits anyway).
257	    // So we check if the number of blocks per split is the same as the previous num_splits.
258	    auto is_split_eligible = [&ceildiv, &num_n_blocks](int num_splits) {
259	        return num_splits == 1 || ceildiv(num_n_blocks, num_splits) != ceildiv(num_n_blocks, num_splits - 1);
260	    };
261	    for (int num_splits = 1; num_splits <= max_splits; num_splits++) {
262	        if (!is_split_eligible(num_splits)) {
263	            efficiency.push_back(0.f);
264	        } else {
265	            float n_waves = float(batch_nheads_mblocks * num_splits) / num_SMs;
266	            float eff = n_waves / ceil(n_waves);
267	            // printf("num_splits = %d, eff = %f\n", num_splits, eff);
268	            if (eff > max_efficiency) { max_efficiency = eff; }
269	            efficiency.push_back(eff);
270	        }
271	    }
272	    for (int num_splits = 1; num_splits <= max_splits; num_splits++) {
273	        if (!is_split_eligible(num_splits)) { continue; }
274	        if (efficiency[num_splits - 1] >= 0.85 * max_efficiency) {
275	            // printf("num_splits chosen = %d\n", num_splits);
276	            return num_splits;
277	        }
278	    }
279	    return 1;
280	}
