534	void set_params_fprop_qpack(Flash_fwd_params &params,
535	    // sizes
536	    const size_t b,
537	    const size_t seqlen_k,
538	    const size_t h, const size_t h_k,
539	    const size_t d,
540	    // device pointers
541	    const at::Tensor k, at::Tensor k_pack, at::Tensor k_params,
542	    const at::Tensor v, at::Tensor v_pack, at::Tensor v_params,
543	    void *cu_seqlens_k_d,
544	    const std::string quant_mode,
545	    const int group_size,
546	    bool page_kv
547	    ) {
548	
549	    // Reset the parameters
550	    params = {};
551	
552	    params.is_bf16 = k.dtype() == torch::kBFloat16;
553	
554	    // Set the pointers and strides.
555	    params.k_ptr = k.data_ptr();
556	    params.K_pack_ptr = k_pack.data_ptr();
557	    params.k_params_ptr = k_params.data_ptr();
558	    params.v_ptr = v.data_ptr();
559	    params.v_pack_ptr = v_pack.data_ptr();
560	    params.v_params_ptr = v_params.data_ptr();
561	    // All stride are in elements, not bytes.
562	    params.k_row_stride = k.stride(-3);
563	    params.K_pack_row_stride = k_pack.stride(-3);
564	    params.k_params_row_stride = k_params.stride(-3);
565	    params.v_row_stride = v.stride(-3);
566	    params.v_pack_row_stride = v_pack.stride(-3);
567	    params.v_params_row_stride = v_params.stride(-1);
568	
569	    params.k_params_dim_stride = k_params.stride(-1);
570	    params.v_params_dim_stride = v_params.stride(-3);
571	
572	    params.k_head_stride = k.stride(-2);
573	    params.K_pack_head_stride = k_pack.stride(-2);
574	    params.k_params_head_stride = k_params.stride(-2);
575	    params.v_head_stride = v.stride(-2);
576	    params.v_pack_head_stride = v_pack.stride(-2);
577	    params.v_params_head_stride = v_params.stride(-2);
578	
579	    if (page_kv) params.k_batch_stride = k.stride(0);
580	    else params.k_batch_stride = seqlen_k * k.size(-2) * k.size(-1);
581	    params.K_pack_batch_stride = k_pack.stride(0);
582	    params.k_params_batch_stride = k_params.stride(0);
583	    if (page_kv) params.v_batch_stride = v.stride(0);
584	    else params.v_batch_stride = seqlen_k * v.size(-2) * v.size(-1);
585	    params.v_pack_batch_stride = v_pack.stride(0);
586	    params.v_params_batch_stride = v_params.stride(0);
587	
588	    params.cu_seqlens_k = static_cast<int *>(cu_seqlens_k_d);
589	
590	    // Set the dimensions.
591	    params.b = b;
592	    params.h = h;
593	    params.h_k = h_k;
594	    params.h_h_k_ratio = h / h_k;
595	    params.seqlen_k = seqlen_k;
596	    params.d = d;
597	
598	    params.quant_mode = quant_mode;
599	    params.group_size = group_size;
600	}
